//! GPU golden-vector tests: the GPU mining kernel and its shader-level Poseidon2
//! implementation must produce byte-identical results to the canonical CPU
//! implementation (pow_core -> qpow-math -> qp-poseidon-core).
//!
//! These tests require a GPU; they skip gracefully when no adapter is available.
//!
//! Golden vectors generated by examples/gen_golden.rs using the canonical
//! CPU implementation. Regenerate if the hash construction ever changes.

use engine_cpu::{EngineStatus, MinerEngine, Range};
use engine_gpu::{precompute_header_state, GpuEngine};
use pow_core::{hash_from_nonce, JobContext};
use primitive_types::U512;
use std::sync::OnceLock;

pub struct GoldenCase {
    pub header_hex: &'static str,
    pub nonce: u64,
    pub hash_hex: &'static str,
}

